INSERT INTO asgard_catalog.careers (id, slug, title, description, responsibilities, skills, category_id, status, editor, source_license, source_urls, reviewed_by, reviewed_at, revision_note, relevance_attributes, revision) VALUES ('1c5a1b58-47c2-569c-9f18-77486cc9d829', 'full-stack-developer', 'Full Stack Developer', 'Build complete, end-to-end web applications combining interactive user interfaces, server-side APIs, and databases.

Representative work: A full-stack web application with user authentication, responsive UI components, REST/GraphQL API endpoints, database persistence, and automated end-to-end tests.', ARRAY['Develop responsive frontend interfaces and bind them to server-side APIs', 'Design relational data models and implement transactional database queries', 'Build secure full-stack authentication, session handling, and authorization flows', 'Leverage server-side rendering (SSR) frameworks for performant web delivery', 'Write end-to-end automated tests and deploy containerized full-stack services']::text[], ARRAY['Full-stack web architecture', 'Modern TypeScript and JavaScript', 'Component-driven UI development', 'Client-side state and data fetching', 'Server-side API routes and middleware', 'Relational data modeling and SQL', 'Server-side rendering (SSR) and hydration', 'End-to-end authentication with cookies and JWTs', 'Automated testing with Playwright or Cypress', 'Docker containerization and CI/CD pipelines']::text[], 'ef1f3d98-5260-5d40-bd8e-8b330bbaf32f', 'published', 'Antigravity', 'Original Asgard-authored summaries; third-party resources linked only and retain their stated licenses', ARRAY['https://developer.mozilla.org/en-US/docs/Learn_web_development/Howto/Web_mechanics/How_the_web_works', 'https://docs.npmjs.com/cli/v10/using-npm/workspaces', 'https://www.typescriptlang.org/docs/handbook/intro.html', 'https://git-scm.com/book/en/v2/Git-Branching-Branching-Workflows', 'https://react.dev/learn/your-first-component', 'https://react.dev/learn/managing-state', 'https://www.w3.org/WAI/tutorials/forms/', 'https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API/Using_Fetch', 'https://expressjs.com/en/guide/routing.html', 'https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Server-side/First_steps/Web_frameworks', 'https://www.postgresql.org/docs/current/tutorial-sql.html', 'https://developer.mozilla.org/en-US/docs/Web/HTTP/Cookies', 'https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Server-side', 'https://react.dev/reference/rsc/server-actions', 'https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content', 'https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Performance', 'https://developer.mozilla.org/en-US/docs/Web/API/File_API/Using_files_from_web_applications', 'https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events/Using_server-sent_events', 'https://developer.mozilla.org/en-US/docs/Web/HTTP/Status/200', 'https://www.postgresql.org/docs/current/tutorial-transactions.html', 'https://playwright.dev/docs/intro', 'https://docs.docker.com/build/building/multi-stage/', 'https://docs.github.com/en/actions/quickstart', 'https://docs.docker.com/guides/walkthroughs/deploy-your-app/']::text[], 'Antigravity (curriculum expansion aligned with roadmap.sh)', '2026-11-04T12:00:00+00:00', 'Owner-requested catalog expansion to add 11 industry-standard careers aligned with roadmap.sh.', '{"activities": ["Develop responsive frontend interfaces and bind them to server-side APIs", "Design relational data models and implement transactional database queries", "Build secure full-stack authentication, session handling, and authorization flows", "Leverage server-side rendering (SSR) frameworks for performant web delivery", "Write end-to-end automated tests and deploy containerized full-stack services"], "scope": "Comprehensive beginner-to-intermediate learning track"}'::jsonb, 1) ON CONFLICT (id) DO NOTHING;
