INSERT INTO asgard_catalog.careers (id, slug, title, description, responsibilities, skills, category_id, status, editor, source_license, source_urls, reviewed_by, reviewed_at, revision_note, relevance_attributes, revision) VALUES ('c5259752-baf4-59ce-9682-596375a5cc7f', 'game-developer', 'Game Developer', 'Design and build 2D and 3D interactive video games using game engines, physics, audio, and gameplay programming.

Representative work: A completed playable 2D/3D action or platformer game featuring player controls, enemy AI, collision physics, health/scoring UI, sound effects, and multi-level progression.', ARRAY['Program core gameplay loops, player movement controllers, and input handling', 'Implement 2D and 3D physics collisions, triggers, and raycasting', 'Build game state machines, inventory systems, and save/load persistence', 'Integrate game sound effects, background music, and user interface HUDs', 'Profile frame rates, optimize memory and draw calls, and export release builds']::text[], ARRAY['Game engine architecture and game loops', '2D sprites, tilesets, and camera viewports', 'Rigidbodies, collision detection, and raycasting', 'Player movement, gravity, and input systems', 'Finite state machines for character behaviors', 'Sprite animation controllers and blend trees', 'Game audio: spatial sound effects and background music', 'Canvas HUDs: health bars, menus, and inventory', 'Game state saving, loading, and scene transitions', 'Frame rate profiling and draw call optimization']::text[], 'ef1f3d98-5260-5d40-bd8e-8b330bbaf32f', 'published', 'Antigravity', 'Original Asgard-authored summaries; third-party resources linked only and retain their stated licenses', ARRAY['https://docs.godotengine.org/en/stable/getting_started/introduction/index.html', 'https://docs.godotengine.org/en/stable/tutorials/math/vector_math.html', 'https://docs.godotengine.org/en/stable/tutorials/scripting/index.html', 'https://docs.godotengine.org/en/stable/getting_started/step_by_step/nodes_and_scenes.html', 'https://docs.godotengine.org/en/stable/tutorials/2d/using_tilemaps.html', 'https://docs.godotengine.org/en/stable/tutorials/physics/physics_introduction.html', 'https://docs.godotengine.org/en/stable/tutorials/inputs/inputevent.html', 'https://docs.godotengine.org/en/stable/tutorials/scripting/nodes_and_scene_instances.html', 'https://docs.godotengine.org/en/stable/tutorials/best_practices/logic_programming.html', 'https://docs.godotengine.org/en/stable/tutorials/2d/2d_sprite_animation.html', 'https://docs.godotengine.org/en/stable/tutorials/audio/audio_buses.html', 'https://docs.godotengine.org/en/stable/tutorials/scripting/pausing_games.html', 'https://docs.godotengine.org/en/stable/tutorials/ui/gui_containers.html', 'https://docs.godotengine.org/en/stable/tutorials/scripting/resources.html', 'https://docs.godotengine.org/en/stable/tutorials/io/saving_games.html', 'https://docs.godotengine.org/en/stable/tutorials/scripting/change_scenes_manually.html', 'https://docs.godotengine.org/en/stable/tutorials/navigation/navigation_introduction_2d.html', 'https://docs.godotengine.org/en/stable/tutorials/2d/2d_particle_systems.html', 'https://docs.godotengine.org/en/stable/tutorials/3d/standard_material_3d.html', 'https://docs.godotengine.org/en/stable/tutorials/3d/lights_and_shadows.html', 'https://docs.godotengine.org/en/stable/tutorials/performance/general_optimization.html', 'https://docs.godotengine.org/en/stable/tutorials/physics/troubleshooting_physics_issues.html', 'https://docs.godotengine.org/en/stable/tutorials/best_practices/index.html', 'https://docs.godotengine.org/en/stable/tutorials/export/exporting_projects.html']::text[], 'Antigravity (curriculum expansion aligned with roadmap.sh)', '2026-11-04T12:00:00+00:00', 'Owner-requested catalog expansion to add 11 industry-standard careers aligned with roadmap.sh.', '{"activities": ["Program core gameplay loops, player movement controllers, and input handling", "Implement 2D and 3D physics collisions, triggers, and raycasting", "Build game state machines, inventory systems, and save/load persistence", "Integrate game sound effects, background music, and user interface HUDs", "Profile frame rates, optimize memory and draw calls, and export release builds"], "scope": "Comprehensive beginner-to-intermediate learning track"}'::jsonb, 1) ON CONFLICT (id) DO NOTHING;
