INSERT INTO asgard_catalog.careers (id, slug, title, description, responsibilities, skills, category_id, status, editor, source_license, source_urls, reviewed_by, reviewed_at, revision_note, relevance_attributes, revision) VALUES ('fe9ab18e-e5fe-5a27-9f57-8c92ec4613b2', 'ai-engineer', 'AI Engineer', 'Build intelligent applications powered by Large Language Models, embeddings, Retrieval-Augmented Generation (RAG), and agentic workflows.

Representative work: A production-ready contextual AI assistant featuring custom RAG document search, structured tool-calling, safety guardrails, token usage tracking, and automated evaluation.', ARRAY['Integrate foundation LLM provider APIs into modern software applications', 'Design, generate, and query vector embeddings using vector databases', 'Implement robust Retrieval-Augmented Generation (RAG) pipelines with evaluation', 'Build autonomous agentic workflows using function calling and tool execution', 'Deploy AI guardrails, monitor prompt latency and token usage, and mitigate hallucinations']::text[], ARRAY['Prompt engineering and system prompts', 'Tokenization, context windows, and model pricing', 'Vector embeddings and similarity search', 'Vector databases (Chroma, Pinecone, pgvector)', 'Retrieval-Augmented Generation (RAG) pipelines', 'Chunking strategies and metadata filtering', 'Function calling and structured JSON outputs', 'Agent orchestration (LangChain / LlamaIndex)', 'Guardrails, prompt injection defense, and safety', 'LLM observability, latency tracking, and evaluation']::text[], 'ef1f3d98-5260-5d40-bd8e-8b330bbaf32f', 'published', 'Antigravity', 'Original Asgard-authored summaries; third-party resources linked only and retain their stated licenses', ARRAY['https://developer.mozilla.org/en-US/docs/Glossary/Artificial_intelligence', 'https://www.promptingguide.ai/introduction/basics', 'https://platform.openai.com/tokenizer', 'https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events', 'https://cloud.google.com/vertex-ai/docs/generative-ai/embeddings/get-text-embeddings', 'https://scikit-learn.org/stable/modules/generated/sklearn.metrics.pairwise.cosine_similarity.html', 'https://github.com/pgvector/pgvector', 'https://python.langchain.com/docs/concepts/#text-splitters', 'https://python.langchain.com/docs/tutorials/rag/', 'https://www.crummy.com/software/BeautifulSoup/bs4/doc/', 'https://cheatsheetseries.owasp.org/cheatsheets/LLM_AI_Security_Cheat_Sheet.html', 'https://docs.ragas.io/en/stable/', 'https://platform.openai.com/docs/guides/function-calling', 'https://python.langchain.com/docs/concepts/#agents', 'https://docs.llamaindex.ai/en/stable/', 'https://python.langchain.com/docs/concepts/#memory', 'https://docs.ragas.io/en/stable/concepts/metrics/index.html', 'https://huggingface.co/docs/peft/index', 'https://cloud.google.com/vertex-ai/docs/generative-ai/pricing', 'https://opentelemetry.io/docs/what-is-opentelemetry/', 'https://developer.mozilla.org/en-US/docs/Web/HTTP/Status/429', 'https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Scripting', 'https://docs.docker.com/guides/walkthroughs/deploy-your-app/']::text[], 'Antigravity (curriculum expansion aligned with roadmap.sh)', '2026-11-04T12:00:00+00:00', 'Owner-requested catalog expansion to add 11 industry-standard careers aligned with roadmap.sh.', '{"activities": ["Integrate foundation LLM provider APIs into modern software applications", "Design, generate, and query vector embeddings using vector databases", "Implement robust Retrieval-Augmented Generation (RAG) pipelines with evaluation", "Build autonomous agentic workflows using function calling and tool execution", "Deploy AI guardrails, monitor prompt latency and token usage, and mitigate hallucinations"], "scope": "Comprehensive beginner-to-intermediate learning track"}'::jsonb, 1) ON CONFLICT (id) DO NOTHING;
DO $asgard_content$ BEGIN IF EXISTS (SELECT 1 FROM asgard_catalog.careers WHERE id = 'fe9ab18e-e5fe-5a27-9f57-8c92ec4613b2' AND (id IS DISTINCT FROM 'fe9ab18e-e5fe-5a27-9f57-8c92ec4613b2' OR slug IS DISTINCT FROM 'ai-engineer' OR title IS DISTINCT FROM 'AI Engineer' OR description IS DISTINCT FROM 'Build intelligent applications powered by Large Language Models, embeddings, Retrieval-Augmented Generation (RAG), and agentic workflows.

Representative work: A production-ready contextual AI assistant featuring custom RAG document search, structured tool-calling, safety guardrails, token usage tracking, and automated evaluation.' OR responsibilities IS DISTINCT FROM ARRAY['Integrate foundation LLM provider APIs into modern software applications', 'Design, generate, and query vector embeddings using vector databases', 'Implement robust Retrieval-Augmented Generation (RAG) pipelines with evaluation', 'Build autonomous agentic workflows using function calling and tool execution', 'Deploy AI guardrails, monitor prompt latency and token usage, and mitigate hallucinations']::text[] OR skills IS DISTINCT FROM ARRAY['Prompt engineering and system prompts', 'Tokenization, context windows, and model pricing', 'Vector embeddings and similarity search', 'Vector databases (Chroma, Pinecone, pgvector)', 'Retrieval-Augmented Generation (RAG) pipelines', 'Chunking strategies and metadata filtering', 'Function calling and structured JSON outputs', 'Agent orchestration (LangChain / LlamaIndex)', 'Guardrails, prompt injection defense, and safety', 'LLM observability, latency tracking, and evaluation']::text[] OR category_id IS DISTINCT FROM 'ef1f3d98-5260-5d40-bd8e-8b330bbaf32f' OR status IS DISTINCT FROM 'published' OR editor IS DISTINCT FROM 'Antigravity' OR source_license IS DISTINCT FROM 'Original Asgard-authored summaries; third-party resources linked only and retain their stated licenses' OR source_urls IS DISTINCT FROM ARRAY['https://developer.mozilla.org/en-US/docs/Glossary/Artificial_intelligence', 'https://www.promptingguide.ai/introduction/basics', 'https://platform.openai.com/tokenizer', 'https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events', 'https://cloud.google.com/vertex-ai/docs/generative-ai/embeddings/get-text-embeddings', 'https://scikit-learn.org/stable/modules/generated/sklearn.metrics.pairwise.cosine_similarity.html', 'https://github.com/pgvector/pgvector', 'https://python.langchain.com/docs/concepts/#text-splitters', 'https://python.langchain.com/docs/tutorials/rag/', 'https://www.crummy.com/software/BeautifulSoup/bs4/doc/', 'https://cheatsheetseries.owasp.org/cheatsheets/LLM_AI_Security_Cheat_Sheet.html', 'https://docs.ragas.io/en/stable/', 'https://platform.openai.com/docs/guides/function-calling', 'https://python.langchain.com/docs/concepts/#agents', 'https://docs.llamaindex.ai/en/stable/', 'https://python.langchain.com/docs/concepts/#memory', 'https://docs.ragas.io/en/stable/concepts/metrics/index.html', 'https://huggingface.co/docs/peft/index', 'https://cloud.google.com/vertex-ai/docs/generative-ai/pricing', 'https://opentelemetry.io/docs/what-is-opentelemetry/', 'https://developer.mozilla.org/en-US/docs/Web/HTTP/Status/429', 'https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Scripting', 'https://docs.docker.com/guides/walkthroughs/deploy-your-app/']::text[] OR reviewed_by IS DISTINCT FROM 'Antigravity (curriculum expansion aligned with roadmap.sh)' OR reviewed_at IS DISTINCT FROM '2026-11-04T12:00:00+00:00' OR revision_note IS DISTINCT FROM 'Owner-requested catalog expansion to add 11 industry-standard careers aligned with roadmap.sh.' OR relevance_attributes IS DISTINCT FROM '{"activities": ["Integrate foundation LLM provider APIs into modern software applications", "Design, generate, and query vector embeddings using vector databases", "Implement robust Retrieval-Augmented Generation (RAG) pipelines with evaluation", "Build autonomous agentic workflows using function calling and tool execution", "Deploy AI guardrails, monitor prompt latency and token usage, and mitigate hallucinations"], "scope": "Comprehensive beginner-to-intermediate learning track"}'::jsonb OR revision IS DISTINCT FROM 1)) THEN RAISE EXCEPTION 'Published content identity already has different values'; END IF; END $asgard_content$;
