INSERT INTO asgard_catalog.careers (id, slug, title, description, responsibilities, skills, category_id, status, editor, source_license, source_urls, reviewed_by, reviewed_at, revision_note, relevance_attributes, revision) VALUES ('c93df31e-9fe9-5ca2-95da-b7b6307d1ab8', 'data-scientist', 'Data Scientist', 'Extract actionable knowledge from complex data using applied statistics, machine learning algorithms, and predictive modeling.

Representative work: An end-to-end data science project including data wrangling, exploratory visualizations, statistical hypothesis testing, machine learning model training, cross-validation evaluation, and SHAP interpretability explanations.', ARRAY['Perform comprehensive exploratory data analysis (EDA) and data cleansing on raw datasets', 'Apply statistical hypothesis testing, probability distributions, and A/B test methodologies', 'Engineer informative features and train supervised and unsupervised machine learning models', 'Evaluate model performance rigorously using cross-validation and error diagnostics', 'Explain model predictions using interpretability techniques and communicate findings clearly']::text[], ARRAY['Python data science stack (NumPy, pandas)', 'Exploratory Data Analysis (EDA)', 'Applied probability and descriptive statistics', 'Hypothesis testing and A/B experimental design', 'Data visualization (Matplotlib, Seaborn)', 'Feature engineering, scaling, and encoding', 'Supervised learning (Regression, Random Forest, XGBoost)', 'Unsupervised learning (K-Means, PCA)', 'Model evaluation metrics (ROC-AUC, RMSE, F1)', 'Model explainability with SHAP values']::text[], 'fcb7e2db-50d6-598c-993a-5adea5d1ced9', 'published', 'Antigravity', 'Original Asgard-authored summaries; third-party resources linked only and retain their stated licenses', ARRAY['https://numpy.org/doc/stable/user/quickstart.html', 'https://pandas.pydata.org/docs/user_guide/10min.html', 'https://scikit-learn.org/stable/tutorial/basic/tutorial.html', 'https://scikit-learn.org/stable/modules/impute.html', 'https://docs.scipy.org/doc/scipy/tutorial/stats.html', 'https://docs.scipy.org/doc/scipy/reference/stats.html', 'https://docs.scipy.org/doc/scipy/reference/generated/scipy.stats.ttest_ind.html', 'https://seaborn.pydata.org/tutorial/introduction.html', 'https://pandas.pydata.org/docs/reference/api/pandas.DataFrame.corr.html', 'https://scikit-learn.org/stable/modules/preprocessing.html', 'https://scikit-learn.org/stable/modules/compose.html#columntransformer-for-heterogeneous-data', 'https://scikit-learn.org/stable/modules/cross_validation.html', 'https://scikit-learn.org/stable/modules/linear_model.html#logistic-regression', 'https://scikit-learn.org/stable/modules/ensemble.html#forests-of-randomized-trees', 'https://scikit-learn.org/stable/modules/ensemble.html#gradient-boosted-trees', 'https://scikit-learn.org/stable/modules/model_evaluation.html#classification-metrics', 'https://scikit-learn.org/stable/modules/model_evaluation.html#regression-metrics', 'https://scikit-learn.org/stable/modules/clustering.html#k-means', 'https://scikit-learn.org/stable/modules/decomposition.html#pca', 'https://scikit-learn.org/stable/modules/grid_search.html', 'https://shap.readthedocs.io/en/latest/index.html', 'https://scikit-learn.org/stable/modules/model_persistence.html', 'https://docs.jupyter.org/en/latest/']::text[], 'Antigravity (curriculum expansion aligned with roadmap.sh)', '2026-11-04T12:00:00+00:00', 'Owner-requested catalog expansion to add 11 industry-standard careers aligned with roadmap.sh.', '{"activities": ["Perform comprehensive exploratory data analysis (EDA) and data cleansing on raw datasets", "Apply statistical hypothesis testing, probability distributions, and A/B test methodologies", "Engineer informative features and train supervised and unsupervised machine learning models", "Evaluate model performance rigorously using cross-validation and error diagnostics", "Explain model predictions using interpretability techniques and communicate findings clearly"], "scope": "Comprehensive beginner-to-intermediate learning track"}'::jsonb, 1) ON CONFLICT (id) DO NOTHING;
