INSERT INTO asgard_catalog.careers (id, slug, title, description, responsibilities, skills, category_id, status, editor, source_license, source_urls, reviewed_by, reviewed_at, revision_note, relevance_attributes, revision) VALUES ('12a912b3-a9f2-5acc-b397-814a61a5ccfd', 'bi-analyst', 'Business Intelligence (BI) Analyst', 'Transform raw business data into actionable executive insights, dimensional data models, and interactive KPI dashboards.

Representative work: An enterprise KPI dashboard suite featuring dimensional data modeling, complex SQL/DAX metrics (YoY growth, customer churn), interactive cross-filtering, row-level security, and executive storytelling slides.', ARRAY['Gather business requirements and translate strategic goals into measurable KPI metrics', 'Design dimensional data models (star schema, fact/dimension tables) for reporting', 'Write complex analytical SQL queries with window functions and multi-table joins', 'Build interactive dashboards and reports in modern BI tools (Power BI, Tableau, Metabase)', 'Implement row-level security, schedule data refreshes, and communicate data storytelling']::text[], ARRAY['KPI definition and metric framework design', 'Dimensional data modeling (star and snowflake schemas)', 'Fact vs dimension tables and surrogate keys', 'Advanced SQL queries and window functions', 'Data warehouse architecture fundamentals', 'Data visualization principles and chart selection', 'Interactive dashboard design (Power BI / Tableau)', 'Calculated measures and time-intelligence expressions', 'Row-level security (RLS) and access governance', 'Executive data storytelling and automated alerts']::text[], 'fcb7e2db-50d6-598c-993a-5adea5d1ced9', 'published', 'Antigravity', 'Original Asgard-authored summaries; third-party resources linked only and retain their stated licenses', ARRAY['https://learn.microsoft.com/en-us/power-bi/fundamentals/power-bi-overview', 'https://learn.microsoft.com/en-us/power-bi/create-reports/service-dashboard-add-widget', 'https://learn.microsoft.com/en-us/power-bi/create-reports/designer-dashboard-best-practices', 'https://learn.microsoft.com/en-us/power-bi/guidance/whitepaper-powerbi-governance', 'https://learn.microsoft.com/en-us/azure/architecture/data-guide/relational-data/online-analytical-processing-olap', 'https://learn.microsoft.com/en-us/power-bi/guidance/star-schema', 'https://www.postgresql.org/docs/current/ddl-constraints.html', 'https://www.postgresql.org/docs/current/tutorial-update.html', 'https://www.postgresql.org/docs/current/queries-table-expressions.html', 'https://www.postgresql.org/docs/current/queries-table-expressions.html#QUERIES-GROUP', 'https://www.postgresql.org/docs/current/tutorial-window.html', 'https://www.postgresql.org/docs/current/queries-with.html', 'https://learn.microsoft.com/en-us/power-bi/connect-data/desktop-connect-to-data', 'https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-types-for-reports', 'https://learn.microsoft.com/en-us/power-bi/create-reports/power-bi-reports-filters-and-highlighting', 'https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-accessibility-creating-reports', 'https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-measures', 'https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-quickstart-learn-dax-basics', 'https://learn.microsoft.com/en-us/power-bi/enterprise/service-admin-rls', 'https://learn.microsoft.com/en-us/power-bi/connect-data/refresh-data', 'https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-drillthrough', 'https://learn.microsoft.com/en-us/power-bi/create-reports/service-set-data-alerts', 'https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-create-distribute-apps']::text[], 'Antigravity (curriculum expansion aligned with roadmap.sh)', '2026-11-04T12:00:00+00:00', 'Owner-requested catalog expansion to add 11 industry-standard careers aligned with roadmap.sh.', '{"activities": ["Gather business requirements and translate strategic goals into measurable KPI metrics", "Design dimensional data models (star schema, fact/dimension tables) for reporting", "Write complex analytical SQL queries with window functions and multi-table joins", "Build interactive dashboards and reports in modern BI tools (Power BI, Tableau, Metabase)", "Implement row-level security, schedule data refreshes, and communicate data storytelling"], "scope": "Comprehensive beginner-to-