INSERT INTO asgard_catalog.careers (id, slug, title, description, responsibilities, skills, category_id, status, editor, source_license, source_urls, reviewed_by, reviewed_at, revision_note, relevance_attributes, revision) VALUES ('d5da6f7f-acfb-5fce-a703-3ee858526264', 'cloud-engineer', 'Cloud Engineer', 'Design, provision, and maintain scalable, reliable cloud infrastructure and services across virtual networks, compute, and storage.

Representative work: A production-grade multi-tier cloud infrastructure provisioned entirely with Terraform, featuring public/private VPC subnets, an auto-scaling compute cluster behind an Application Load Balancer, a managed database, and automated CloudWatch alarms.', ARRAY['Architect and provision resilient cloud infrastructure using Infrastructure as Code (Terraform)', 'Configure secure virtual private clouds (VPCs), subnets, routing tables, and gateways', 'Deploy and scale compute workloads using virtual machines, containers, and serverless functions', 'Manage cloud storage lifecycle policies, relational and NoSQL databases, and CDNs', 'Implement automated monitoring, resource alarms, backup policies, and disaster recovery']::text[], ARRAY['Cloud service models (IaaS, PaaS, Serverless)', 'Cloud global infrastructure and regions', 'Virtual Private Clouds (VPC) and CIDR subnets', 'Compute instances, auto-scaling, and load balancing', 'Cloud storage (S3/Blob) and lifecycle policies', 'Managed relational and NoSQL database services', 'Infrastructure as Code (IaC) with Terraform', 'DNS management, routing, and CDN distribution', 'Cloud monitoring, metrics, and automated alerting', 'High availability and disaster recovery planning']::text[], 'f37c7fa6-afc6-5a89-ac6a-283be8473168', 'published', 'Antigravity', 'Original Asgard-authored summaries; third-party resources linked only and retain their stated licenses', ARRAY['https://aws.amazon.com/types-of-cloud-computing/', 'https://aws.amazon.com/about-aws/global-infrastructure/', 'https://docs.aws.amazon.com/cli/latest/userguide/cli-chap-welcome.html', 'https://docs.aws.amazon.com/cost-management/latest/userguide/budgets-managing-costs.html', 'https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/concepts.html', 'https://docs.aws.amazon.com/lambda/latest/dg/welcome.html', 'https://docs.aws.amazon.com/autoscaling/ec2/userguide/what-is-amazon-ec2-auto-scaling.html', 'https://docs.aws.amazon.com/elasticloadbalancing/latest/application/introduction.html', 'https://docs.aws.amazon.com/vpc/latest/userguide/what-is-amazon-vpc.html', 'https://docs.aws.amazon.com/vpc/latest/userguide/vpc-nat-gateway.html', 'https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/Welcome.html', 'https://docs.aws.amazon.com/vpc/latest/peering/what-is-vpc-peering.html', 'https://docs.aws.amazon.com/AmazonS3/latest/userguide/Welcome.html', 'https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Welcome.html', 'https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/Introduction.html', 'https://docs.aws.amazon.com/AmazonCloudFront/latest/DeveloperGuide/Introduction.html', 'https://developer.hashicorp.com/terraform/intro', 'https://developer.hashicorp.com/terraform/language', 'https://developer.hashicorp.com/terraform/language/state/backends', 'https://developer.hashicorp.com/terraform/language/modules', 'https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/WhatIsCloudWatch.html', 'https://docs.aws.amazon.com/aws-backup/latest/devguide/whatisbackup.html', 'https://docs.aws.amazon.com/whitepapers/latest/disaster-recovery-workloads-on-aws/disaster-recovery-options-in-the-cloud.html', 'https://docs.aws.amazon.com/whitepapers/latest/web-application-hosting-best-practices/an-aws-cloud-architecture-for-web-hosting.html']::text[], 'Antigravity (curriculum expansion aligned with roadmap.sh)', '2026-11-04T12:00:00+00:00', 'Owner-requested catalog expansion to add 11 industry-standard careers aligned with roadmap.sh.', '{"activities": ["Architect and provision resilient cloud infrastructure using Infrastructure as Code (Terraform)", "Configure secure virtual private clouds (VPCs), subnets, routing tables, and gateways", "Deploy and scale compute workloads using virtual machines, containers, and serverless functions", "Manage cloud storage lifecycle policies, relational and NoSQL databases, and CDNs", "Implement automated monitoring, resource alarms, backup policies, and disaster recovery"], "scope": "Comprehensive beginner-to-intermediate learning track"}'::jsonb, 1) ON CONFLICT (id) DO NOTHING;
