INSERT INTO asgard_catalog.careers (id, slug, title, description, responsibilities, skills, category_id, status, editor, source_license, source_urls, reviewed_by, reviewed_at, revision_note, relevance_attributes, revision) VALUES ('e46a121b-b0b8-5e62-bedd-ebd9303f2eca', 'system-administrator', 'System Administrator', 'Administer, secure, and maintain enterprise Linux servers, operating system storage, user access, services, and network connectivity.

Representative work: A hardened, production-ready enterprise Linux server deployment featuring LVM partitioned storage, non-root sudo accounts, hardened SSH key authentication, automated systemd service management, firewall rules, and automated rsync backup scripts.', ARRAY['Install, configure, and maintain Linux operating systems and enterprise distributions', 'Manage user accounts, group permissions, PAM authentication, and SSH access controls', 'Partition disks, configure Logical Volume Management (LVM), and manage filesystems', 'Control background services and daemons using systemd and automate tasks with cron and Bash', 'Configure host firewalls, monitor system logs with journalctl, and execute disaster recovery backups']::text[], ARRAY['Linux filesystem hierarchy and terminal navigation', 'Superuser privileges and sudo configuration', 'User and group account administration', 'Linux file permissions (chmod, chown, SUID/SGID)', 'Storage partitioning and Logical Volume Management (LVM)', 'Package management with APT and DNF/YUM', 'Process control and systemd service units', 'Bash scripting and scheduled cron automation', 'Host firewall configuration (UFW and nftables)', 'System log auditing and rsync backup automation']::text[], 'f37c7fa6-afc6-5a89-ac6a-283be8473168', 'published', 'Antigravity', 'Original Asgard-authored summaries; third-party resources linked only and retain their stated licenses', ARRAY['https://ubuntu.com/server/docs', 'https://tldp.org/LDP/intro-linux/html/sect_03_01.html', 'https://tldp.org/LDP/intro-linux/html/sect_05_01.html', 'https://man7.org/linux/man-pages/man8/sudo.8.html', 'https://man7.org/linux/man-pages/man8/useradd.8.html', 'https://tldp.org/LDP/intro-linux/html/sect_03_04.html', 'https://man7.org/linux/man-pages/man5/sshd_config.5.html', 'https://man7.org/linux/man-pages/man8/pam.8.html', 'https://man7.org/linux/man-pages/man8/fdisk.8.html', 'https://man7.org/linux/man-pages/man8/lvm.8.html', 'https://man7.org/linux/man-pages/man5/fstab.5.html', 'https://man7.org/linux/man-pages/man8/apt.8.html', 'https://man7.org/linux/man-pages/man1/ps.1.html', 'https://man7.org/linux/man-pages/man5/systemd.service.5.html', 'https://man7.org/linux/man-pages/man5/crontab.5.html', 'https://tldp.org/LDP/Bash-Beginners-Guide/html/', 'https://man7.org/linux/man-pages/man8/ip.8.html', 'https://man7.org/linux/man-pages/man5/resolv.conf.5.html', 'https://man7.org/linux/man-pages/man8/ufw.8.html', 'https://man7.org/linux/man-pages/man8/ss.8.html', 'https://man7.org/linux/man-pages/man1/journalctl.1.html', 'https://man7.org/linux/man-pages/man8/logrotate.8.html', 'https://man7.org/linux/man-pages/man1/rsync.1.html', 'https://man7.org/linux/man-pages/man1/chroot.1.html']::text[], 'Antigravity (curriculum expansion aligned with roadmap.sh)', '2026-11-04T12:00:00+00:00', 'Owner-requested catalog expansion to add 11 industry-standard careers aligned with roadmap.sh.', '{"activities": ["Install, configure, and maintain Linux operating systems and enterprise distributions", "Manage user accounts, group permissions, PAM authentication, and SSH access controls", "Partition disks, configure Logical Volume Management (LVM), and manage filesystems", "Control background services and daemons using systemd and automate tasks with cron and Bash", "Configure host firewalls, monitor system logs with journalctl, and execute disaster recovery backups"], "scope": "Comprehensive beginner-to-intermediate learning track"}'::jsonb, 1) ON CONFLICT (id) DO NOTHING;
